3	namespace App\Http\Controllers\Api\PublicSite;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\HashesClientData;
7	use App\Http\Controllers\Concerns\ResolvesSubdomainFromHost;
8	use App\Http\Requests\Api\PublicSite\PublicEnquiryRequest;
9	use App\Jobs\Notifications\SendEnquiryNotificationJob;
10	use App\Models\Analytics\LeadSubmission;
11	use App\Models\Core\Professional\Customer;
12	use App\Models\Core\Site\Block;
13	use App\Models\Core\Site\Enquiry;
14	use App\Services\Public\PublicSiteResolver;
15	use Illuminate\Http\JsonResponse;
16	use Illuminate\Http\Request;
17	use Illuminate\Support\Facades\RateLimiter;
18	
19	// V2: Handles public contact form submissions. Saves enquiry, upserts submitter as Customer lead, dispatches notification email.
20	class PublicEnquiryController extends ApiController
21	{
22	    use HashesClientData;
23	    use ResolvesSubdomainFromHost;
24	
25	    public function submit(PublicEnquiryRequest $request, PublicSiteResolver $resolver): JsonResponse
26	    {
27	        $data = $request->validated();
28	
29	        $subdomain = $this->resolveSiteSubdomain($request);
30	        $startedMs = $data['form_started_at_ms'] ?? null;
31	
32	        // 1) Honeypot: pretend success but record the abuse attempt.
33	        $honeypot = $data['website'] ?? null;
34	        if (is_string($honeypot) && trim($honeypot) !== '') {
35	            $this->logLead($request, $subdomain, null, null, 'honeypot', $startedMs);
36	
37	            return $this->success(['ok' => true]);
38	        }
39	
40	        // 2) Timing check: reject fires that are implausibly fast or old.
41	        if (is_int($startedMs)) {
42	            $nowMs = (int) floor(microtime(true) * 1000);
43	            $delta = $nowMs - $startedMs;
44	            $minMs = (int) config('partna.form_timing.min_ms', 2500);
45	            $maxMs = (int) config('partna.form_timing.max_ms', 12 * 60 * 60 * 1000);
46	
47	            if ($delta < $minMs || $delta > $maxMs) {
48	                $this->logLead($request, $subdomain, null, null, 'too_fast', $startedMs);
49	
50	                return $this->error('Invalid submission.', 422);
51	            }
52	        }
53	
54	        if (! $subdomain) {
55	            $this->logLead($request, null, null, null, 'no_subdomain', $startedMs);
56	
57	            return $this->error('Could not determine site from URL.', 400);
58	        }
59	
60	        $site = $resolver->resolvePublishedSite($subdomain);
61	        if (! $site || ! $site->professional_id) {
62	            $this->logLead($request, $subdomain, $site?->id, null, 'site_not_found', $startedMs);
63	
64	            return $this->error('Site not found.', 404);
65	        }
66	
67	        // 3) Contact block must be active on this site.
68	        $block = Block::query()
69	            ->where('site_id', $site->id)
70	            ->where('block_group', 'sections')
71	            ->where('block_type', 'contact')
72	            ->where('is_active', true)
73	            ->whereNull('deleted_at')
74	            ->first();
75	
76	        if (! $block) {
77	            return $this->error('This site is not accepting enquiries.', 422);
78	        }
79	
80	        // 4) Validate subject against merged options (platform defaults + affiliate additions).
81	        $defaults = (array) config('partna.contact_subject_defaults', []);
82	        $custom = data_get($block->settings, 'subject_options');
83	        $custom = is_array($custom) ? $custom : [];
84	        $mergedOptions = array_values(array_unique(array_merge($defaults, $custom)));
85	
86	        if (! in_array($data['subject'], $mergedOptions, true)) {
87	            return $this->error('Invalid subject.', 422);
88	        }
89	
90	        // 5) Save the enquiry.
91	        $enquiry = Enquiry::query()->create([
92	            'professional_id' => $site->professional_id,
93	            'site_id' => $site->id,
94	            'name' => $data['name'],
95	            'email' => $data['email'],
96	            'phone' => $data['phone'] ?? null,
97	            'subject' => $data['subject'],
98	            'message' => $data['message'],
99	            'ip_hash' => $this->hashIp($request->ip()),
100	            'user_agent' => mb_substr((string) $request->userAgent(), 0, 500),
101	        ]);
102	
103	        // 6) Upsert submitter as Customer lead.
104	        $this->upsertEnquiryCustomer((string) $site->professional_id, $data['email'], $data['name'], $data['phone'] ?? null);
105	
106	        // 7) Log unified lead analytics.
107	        $this->logLead($request, $subdomain, $site->id, (string) $site->professional_id, 'created', $startedMs);
108	
109	        // 8) Dispatch notification email (only if settings.notification_email is present and per-brand hourly limit not reached).
110	        $notificationEmail = data_get($block->settings, 'notification_email');
111	        if (is_string($notificationEmail) && trim($notificationEmail) !== '') {
112	            $notifyKey = 'enquiry_notify:'.$site->professional_id;
113	            $notifyLimit = config('partna.throttle.enquiry_notification_per_hour', 10);
114	
115	            if (! RateLimiter::tooManyAttempts($notifyKey, $notifyLimit)) {
116	                RateLimiter::hit($notifyKey, 3600);
117	                SendEnquiryNotificationJob::dispatch((string) $enquiry->id, trim($notificationEmail));
118	            }
119	        }
120	
121	        return $this->success(['ok' => true]);
122	    }
123	
124	    private function upsertEnquiryCustomer(string $professionalId, string $email, ?string $fullName, ?string $phone): void
125	    {
126	        $normalizedEmail = strtolower(trim($email));
127	        if ($normalizedEmail === '') {
128	            return;
129	        }
130	
131	        $existing = Customer::query()
132	            ->withTrashed()
133	            ->where('professional_id', $professionalId)
134	            ->whereRaw('lower(email) = ?', [$normalizedEmail])
135	            ->first();
136	
137	        if ($existing) {
138	            if ($existing->trashed()) {
139	                $existing->restore();
140	            }
141	
142	            if ($fullName && trim((string) ($existing->full_name ?? '')) === '') {
143	                $existing->full_name = $fullName;
144	            }
145	
146	            if ($phone && trim((string) ($existing->phone ?? '')) === '') {
147	                $existing->phone = $phone;
148	            }
149	
150	            if (($existing->source ?? '') === '') {
151	                $existing->source = 'enquiry';
152	            }
153	
154	            $existing->save();
155	
156	            return;
157	        }
158	
159	        $customer = new Customer;
160	        $customer->professional_id = $professionalId;
161	        $customer->email = $normalizedEmail;
162	        $customer->full_name = $fullName ?: null;
163	        $customer->phone = $phone ?: null;
164	        $customer->source = 'enquiry';
165	        $customer->save();
166	    }
167	
168	    private function logLead(
169	        Request $request,
170	        ?string $subdomain,
171	        ?string $siteId,
172	        ?string $professionalId,
173	        string $outcome,
174	        ?int $formStartedAtMs,
175	    ): void {
176	        LeadSubmission::query()->create([
177	            'occurred_at' => now(),
178	            'subdomain' => $subdomain,
179	            'site_id' => $siteId,
180	            'professional_id' => $professionalId,
181	            'customer_id' => null,
182	            'ip_hash' => $this->hashIp($request->ip()),
183	            'user_agent' => $request->userAgent(),
184	            'referrer' => $request->headers->get('referer'),
185	            'outcome' => $outcome,
186	            'form_started_at_ms' => $formStartedAtMs,
187	        ]);
188	    }
189	}
