9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Support\Facades\DB;
11	use Illuminate\Support\Str;
12	
13	// V2: Captures waitlist signups with applicant type, industry, team size, and pilot program opt-in.
14	class PublicWaitlistController extends ApiController
15	{
16	    use HashesClientData;
17	
18	    public function store(PublicWaitlistSignupRequest $request): JsonResponse
19	    {
20	        $data = $request->validated();
21	        $email = mb_strtolower(trim((string) $data['email']));
22	        $submittedAt = now();
23	
24	        // Email-only signups (e.g. coming-soon landing) leave most fields null; full
25	        // waitlist form submissions fill them in. Both paths flow through this payload.
26	        $payload = [
27	            'name' => $data['name'] ?? null,
28	            'email' => $email,
29	            'email_lc' => $email,
30	            'phone' => $data['phone'] ?? null,
31	            'applicant_type' => $data['type'] ?? null,
32	            'applicant_type_other' => $data['type_other_text'] ?? null,
33	            'industry' => $data['industry'] ?? null,
34	            'industry_other' => $data['industry_other_text'] ?? null,
35	            'pilot_program_opt_in' => (bool) ($data['pilot_program_opt_in'] ?? false),
36	            'number_of_team_members' => $data['number_of_team_members'] ?? null,
37	            'number_of_affiliates_ambassadors' => $data['number_of_affiliates_ambassadors'] ?? null,
38	            'is_brand_partner_or_ambassador' => $data['is_brand_partner_or_ambassador'] ?? null,
39	            'currently_sells_products' => $data['currently_sells_products'] ?? null,
40	            'consent_source' => 'waitlist_form',
41	            'consent_ip_hash' => $this->hashIp($request->ip()),
42	            'consent_user_agent' => mb_substr((string) ($request->userAgent() ?? ''), 0, 500) ?: null,
43	            'last_submitted_at' => $submittedAt,
44	        ];
45	
46	        $signup = $this->upsertWaitlistSignup($email, $payload);
47	
48	        return $this->success(['ok' => true], $signup->wasRecentlyCreated ? 201 : 200);
49	    }
50	
51	    private function upsertWaitlistSignup(string $emailLc, array $payload): WaitlistSignup
52	    {
53	        $wasInserted = DB::table('core.waitlist_signups')
54	            ->where('email_lc', $emailLc)
55	            ->doesntExist();
56	
57	        WaitlistSignup::query()->upsert(
58	            [array_merge($payload, ['id' => (string) Str::uuid()])],
59	            ['email_lc'],
60	            array_keys(array_diff_key($payload, array_flip(['email_lc'])))
61	        );
62	
63	        $signup = WaitlistSignup::query()->where('email_lc', $emailLc)->firstOrFail();
64	
65	        // Simulate wasRecentlyCreated for status code logic
66	        if ($wasInserted) {
67	            // Use reflection or a flag since upsert doesn't set wasRecentlyCreated
68	            $signup->wasRecentlyCreated = true;
69	        }
70	
71	        return $signup;
72	    }
73	}
