13	
14	// V2: JWT authentication via Supabase JWKS (asymmetric). Falls back to Auth Server query. All authenticated routes require this.
15	class VerifySupabaseJwt
16	{
17	    /**
18	     * Process-local memo of parsed JWKS keys, keyed by a hash of the raw JWKS
19	     * payload. JWK::parseKeySet() rebuilds OpenSSL EC public-key resources from
20	     * JSON on every call (~150-300ms for ES256 — dominates the auth path) but
21	     * the JWKS itself rarely changes; caching the parsed Key map across requests
22	     * within a PHP-FPM worker drops repeat-request cost to a single signature
23	     * verification (~5-15ms). Hashing the payload means a Supabase signing-key
24	     * rotation invalidates the memo automatically (the JWKS Redis cache TTL is
25	     * 5 min, so we pick up rotations within that window). Capped at 4 entries
26	     * to bound long-running-worker memory across multiple rotations.
27	     *
28	     * @var array<string, array<string, \Firebase\JWT\Key>>
29	     */
30	    private static array $parsedKeysByJwksHash = [];
31	
32	    /**
33	     * Hash of the most recently loaded JWKS payload. Identifies which entry of
34	     * $parsedKeysByJwksHash is the "current" map — used by the fast-path that
35	     * skips Redis when a recent parsed map already contains the requested kid.
36	     */
37	    private static ?string $jwksCurrentHash = null;
38	
39	    /**
40	     * Monotonic millis of the last successful JWKS load (Redis hit OR closure
41	     * refresh). The Redis-skip fast path is only taken while this is fresh.
42	     */
43	    private static ?int $jwksLoadedAtMs = null;
44	
45	    /**
46	     * Process-local TTL on the Redis-skip fast path. Independent of the upstream
47	     * Redis cache's TTL: this only governs how long a worker trusts its in-memory
48	     * parsed map without re-checking Redis. A new kid (rotation) bypasses the
49	     * fast path automatically — the cache.get below picks up the new payload.
50	     */
51	    private const JWKS_FRESH_TTL_MS = 60_000;
52	
53	    public function __construct(private CacheLockService $cacheLock) {}
54	
55	    public function handle(Request $request, Closure $next): Response
56	    {
57	        $token = $this->getBearerToken($request);
58	        if (! $token) {
59	            return response()->json(['message' => 'Missing Bearer token'], 401);
60	        }
61	
62	        // 1) Try verify via JWKS (asymmetric signing)
63	        try {
64	            $claims = $this->verifyWithJwks($token);
65	
66	            // Validate issuer/audience (extra safety)
67	            if (! $this->claimsMatchConfig($claims)) {
68	                return response()->json(['message' => 'Invalid token claims'], 401);
69	            }
70	
71	            $uid = $claims['sub'] ?? null;
72	            if (! $uid) {
73	                return response()->json(['message' => 'Token missing sub'], 401);
74	            }
75	
76	            $this->setSupabaseContext($request, $uid, $claims);
77	
78	            return $next($request);
79	        } catch (\Throwable $e) {
80	            // Log every JWKS failure before falling back — repeated infra-level failures
81	            // (e.g. network blocking JWKS fetches) are security-relevant and must be visible.
82	            Log::warning('JWT JWKS verification failed, falling back to auth server', [
83	                'reason' => $e->getMessage(),
84	                'ip' => $request->ip(),
85	            ]);
86	
87	            // Fail-closed mode: refuse to fall back to Auth-Server during JWKS outage.
88	            // Set SUPABASE_JWKS_FAIL_CLOSED=true in production if you prefer hard failures
89	            // over the reduced-security fallback path.
90	            if (config('supabase.jwks_fail_closed', false)) {
91	                return response()->json(['message' => 'Service unavailable'], 503);
92	            }
93	
94	            // 2) Fallback for legacy/shared-secret setups:
95	            // Supabase recommends verifying by calling Auth server /user. :contentReference[oaicite:2]{index=2}
96	            try {
97	                $uid = $this->verifyWithAuthServer($token);
98	                if (! $uid) {
99	                    return response()->json(['message' => 'Invalid token'], 401);
100	                }
101	
102	                $this->setSupabaseContext($request, $uid);
103	
104	                return $next($request);
105	            } catch (\Throwable $e2) {
106	                Log::warning('JWT verification failed', [
107	                    'reason' => $e2->getMessage(),
108	                    'ip' => $request->ip(),
109	                ]);
110	
111	                return response()->json(['message' => 'Invalid token'], 401);
112	            }
113	        }
114	    }
115	
116	    private function getBearerToken(Request $request): ?string
117	    {
118	        $auth = (string) $request->header('Authorization', '');
119	        if (! str_starts_with($auth, 'Bearer ')) {
120	            return null;
121	        }
122	
123	        return trim(substr($auth, 7));
124	    }
125	
126	    private function setSupabaseContext(Request $request, string $uid, ?array $claims = null): void
127	    {
128	        $request->attributes->set('supabase_uid', $uid);
129	
130	        if ($claims !== null) {
131	            $request->attributes->set('supabase_claims', $claims);
132	        }
133	
134	        // Nightwatch falls back to hidden context when no Laravel auth guard is resolved.
135	        if (class_exists(\Laravel\Nightwatch\Compatibility::class)) {
136	            \Laravel\Nightwatch\Compatibility::addUserIdToContext($uid);
137	        }
138	    }
139	
140	    private function verifyWithJwks(string $jwt): array
141	    {
142	        $parts = explode('.', $jwt);
143	        if (count($parts) !== 3) {
144	            throw new \RuntimeException('Invalid JWT format');
145	        }
146	
147	        $header = json_decode($this->b64urlDecode($parts[0]), true) ?: [];
148	
149	        // Reject non-asymmetric algorithms before key lookup to prevent algorithm confusion attacks
150	        // (e.g. HS256 signed with the public key as the HMAC secret). RS256 and ES256 are both
151	        // asymmetric — Supabase issues ES256 by default for projects on migrated signing keys, so
152	        // both must be accepted here. NEVER add HS256 to this allowlist.
153	        $alg = $header['alg'] ?? null;
154	        if (! in_array($alg, ['RS256', 'ES256'], true)) {
155	            throw new \RuntimeException('JWT alg must be RS256 or ES256, got: '.($alg ?? 'none'));
156	        }
157	
158	        $kid = $header['kid'] ?? null;
159	        if (! $kid) {
160	            throw new \RuntimeException('JWT header missing kid');
161	        }
162	
163	        $nowMs = (int) (microtime(true) * 1000);
164	
165	        // Redis-skip fast path: if this worker has loaded JWKS within the last
166	        // JWKS_FRESH_TTL_MS *and* the current parsed map already contains the
167	        // kid this token was signed with, verify directly. This eliminates the
168	        // 100–300ms supabase:jwks Redis round-trip (and any SWR-triggered
169	        // closure refresh that would otherwise fire HTTP at Supabase) from the
170	        // common authenticated-request path. Rotations bypass this branch
171	        // automatically — a new kid won't be in the memoised map, so we fall
172	        // through to the cache.get below which has its own (5 min) TTL.
173	        if (
174	            self::$jwksCurrentHash !== null
175	            && self::$jwksLoadedAtMs !== null
176	            && ($nowMs - self::$jwksLoadedAtMs) < self::JWKS_FRESH_TTL_MS
177	            && isset(self::$parsedKeysByJwksHash[self::$jwksCurrentHash][$kid])
178	        ) {
179	            JWT::$leeway = 60;
180	            $decoded = JWT::decode($jwt, self::$parsedKeysByJwksHash[self::$jwksCurrentHash][$kid]);
181	
182	            return json_decode(json_encode($decoded), true) ?: [];
183	        }
184	
185	        $jwksUrl = config('supabase.jwks_url');
186	        if (! $jwksUrl) {
187	            throw new \RuntimeException('Missing SUPABASE_JWKS_URL');
188	        }
189	
190	        $jwks = $this->cacheLock->rememberLocked('supabase:jwks', config('supabase.jwks_cache_seconds', 300), function () use ($jwksUrl) {
191	            $res = Http::timeout(5)->get($jwksUrl);
192	            if (! $res->ok()) {
193	                throw new \RuntimeException('Failed to fetch JWKS');
194	            }
195	
196	            $payload = $res->json();
197	            if (! is_array($payload)) {
198	                // Empty/invalid JSON body — never cache this. Throwing keeps the lock-release
199	                // path clean and lets the caller's error logging surface the infra problem.
200	                throw new \RuntimeException('JWKS response did not parse to an array');
201	            }
202	
203	            return $payload;
204	        });
205	
206	        // If your project isn't using asymmetric keys, JWKS may be empty. :contentReference[oaicite:3]{index=3}
207	        if (empty($jwks['keys'])) {
208	            throw new \RuntimeException('JWKS empty');
209	        }
210	
211	        $jwksHash = md5((string) json_encode($jwks));
212	        if (! isset(self::$parsedKeysByJwksHash[$jwksHash])) {
213	            // Bound worker memory across multiple key rotations — drop the oldest
214	            // entry once we already hold a small set of recent JWKS payloads.
215	            if (count(self::$parsedKeysByJwksHash) >= 4) {
216	                array_shift(self::$parsedKeysByJwksHash);
217	            }
218	            self::$parsedKeysByJwksHash[$jwksHash] = JWK::parseKeySet($jwks);
219	        }
220	
221	        // Mark this hash as the current JWKS map for the worker's fast path.
222	        // Updated on every successful Redis fetch so a rotation transition
223	        // pivots the fast path onto the new payload as soon as one request
224	        // pays the cache.get cost.
225	        self::$jwksCurrentHash = $jwksHash;
226	        self::$jwksLoadedAtMs = $nowMs;
227	
228	        $keys = self::$parsedKeysByJwksHash[$jwksHash];
229	        $key = $keys[$kid] ?? null;
230	        if (! $key) {
231	            throw new \RuntimeException('No matching JWKS key for kid');
232	        }
233	
234	        // Decode + verify signature + exp/nbf automatically
235	        JWT::$leeway = 60; // clock skew tolerance
236	        $decoded = JWT::decode($jwt, $key);
237	
238	        return json_decode(json_encode($decoded), true) ?: [];
239	    }
