241	    private function verifyWithAuthServer(string $jwt): ?string
242	    {
243	        $baseUrl = rtrim((string) config('supabase.url'), '/');
244	        $anonKey = (string) config('supabase.anon_key');
245	
246	        if (! $baseUrl || ! $anonKey) {
247	            throw new \RuntimeException('Missing SUPABASE_URL or SUPABASE_ANON_KEY');
248	        }
249	
250	        // Validate iss/aud from the token payload before calling Auth-Server.
251	        // Auth-Server verifies the signature, but doesn't protect against cross-project
252	        // tokens (a valid token from another Supabase project would pass otherwise).
253	        $claims = $this->extractJwtPayloadClaims($jwt);
254	        if (! $this->claimsMatchConfig($claims)) {
255	            return null;
256	        }
257	
258	        $res = Http::timeout(5)
259	            ->withHeaders([
260	                'apikey' => $anonKey,
261	                'Authorization' => 'Bearer '.$jwt,
262	            ])
263	            ->get($baseUrl.'/auth/v1/user');
264	
265	        if (! $res->ok()) {
266	            return null;
267	        }
268	
269	        $user = $res->json();
270	        $uid = $user['id'] ?? null;
271	
272	        // Reject if Supabase returns a non-UUID — guards against misconfig or unexpected response shapes.
273	        if (! $uid || ! $this->isValidUuid($uid)) {
274	            return null;
275	        }
276	
277	        return $uid;
278	    }
279	
280	    /** Decode JWT payload without signature verification — used only to read claims in the fallback path. */
281	    private function extractJwtPayloadClaims(string $jwt): array
282	    {
283	        $parts = explode('.', $jwt);
284	        if (count($parts) !== 3) {
285	            return [];
286	        }
287	
288	        return json_decode($this->b64urlDecode($parts[1]), true) ?: [];
289	    }
290	
291	    private function isValidUuid(string $value): bool
292	    {
293	        return (bool) preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i', $value);
294	    }
295	
296	    private function claimsMatchConfig(array $claims): bool
297	    {
298	        $issExpected = (string) config('supabase.jwt_issuer');
299	        $audExpected = (string) config('supabase.jwt_audience');
300	
301	        if ($issExpected && (($claims['iss'] ?? null) !== $issExpected)) {
302	            return false;
303	        }
304	
305	        $aud = $claims['aud'] ?? null;
306	        if ($audExpected) {
307	            if (is_array($aud)) {
308	                if (! in_array($audExpected, $aud, true)) {
309	                    return false;
310	                }
311	            } else {
312	                if ($aud !== $audExpected) {
313	                    return false;
314	                }
315	            }
316	        }
317	
318	        return true;
319	    }
320	
321	    private function b64urlDecode(string $data): string
322	    {
323	        $data = strtr($data, '-_', '+/');
324	        $pad = strlen($data) % 4;
325	        if ($pad) {
326	            $data .= str_repeat('=', 4 - $pad);
327	        }
328	
329	        return base64_decode($data) ?: '';
330	    }
331	}
